cd /var/www/html && python3 - <<'E'
p='templates/_layouts/default.twig'
s=open(p).read()
s=s.replace('''  <link rel="stylesheet" href="https://knecht.works/styleguide/kit.css">''','''  <script>
    (function () {
      var t = localStorage.getItem('theme');
      var dark = t ? t === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches;
      document.documentElement.classList.toggle('kit-light', !dark);
    })();
  </script>
  <link rel="stylesheet" href="https://knecht.works/styleguide/kit.css">''',1)
s=s.replace('<body class="kit-body kit-light">','<body class="kit-body">')
s=s.replace('''            <label for="language-switcher"''','''            <button type="button" id="theme-toggle" class="cursor-pointer" aria-label="Toggle dark mode">
              <span data-theme-icon="sun" class="hidden"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg></span>
              <span data-theme-icon="moon" class="hidden"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg></span>
            </button>
            <label for="language-switcher"''',1)
s=s.replace('class="text-black!"','style="color: var(--kit-ink)"').replace('class="flex items-center text-black!"','class="flex items-center" style="color: var(--kit-ink)"')
open(p,'w').write(s)
open('src/js/app.js','a').write('''
const root = document.documentElement
const toggle = document.getElementById('theme-toggle')

function syncIcons() {
  const light = root.classList.contains('kit-light')
  document.querySelector('[data-theme-icon="sun"]')?.classList.toggle('hidden', light)
  document.querySelector('[data-theme-icon="moon"]')?.classList.toggle('hidden', !light)
}

toggle?.addEventListener('click', () => {
  const light = root.classList.toggle('kit-light')
  localStorage.setItem('theme', light ? 'light' : 'dark')
  syncIcons()
})
syncIcons()
''')
E
grep -n "text-black\|kit-ink" templates/_layouts/default.twig; curl -s localhost -o /dev/null -w "%{http_code}\n"

